      id TEXT PRIMARY KEY,
      title TEXT NOT NULL,
      root_node_id TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    );

    CREATE INDEX IF NOT EXISTS sessions_updated_at ON sessions(updated_at);

    CREATE TABLE IF NOT EXISTS nodes (
      id TEXT PRIMARY KEY,
      session_id TEXT NOT NULL,
      parent_id TEXT,
      parent_anchor_text TEXT,
      question TEXT NOT NULL,
      response TEXT NOT NULL DEFAULT '',
      status TEXT NOT NULL DEFAULT 'streaming',
      error_message TEXT,
      sibling_index INTEGER NOT NULL DEFAULT 0,
      token_input INTEGER NOT NULL DEFAULT 0,
      token_output INTEGER NOT NULL DEFAULT 0,
      created_at INTEGER NOT NULL,
      FOREIGN KEY (session_id) REFERENCES sessions(id) ON DELETE CASCADE
    );

    CREATE INDEX IF NOT EXISTS nodes_session ON nodes(session_id);
    CREATE INDEX IF NOT EXISTS nodes_parent ON nodes(parent_id);
  `);

  ensureHerdrSchema(db);

  if (!db.prepare("SELECT 1 FROM pragma_table_info('sessions') WHERE name = 'binding_type'").get()) {

