  const now = args.now ?? Date.now();
  const bot = getLarkBotRecord(args.botId);
  if (!bot) {
    return { ok: false, message: `未找到机器人 ${args.botId}` };
  }

  let member: LarkBotMemberRecord | null = null;
  if (args.openIdOrCode.id) {
