      } catch {
        pendingMsg = null;
      }
    }

    if (pendingMsg && pendingMsg.messageId) {
      const expired = isMessageExpiredForReplay(member.appliedAt, now);
      const chatId = member.pendingChatId || pendingMsg.chatId;

      if (!expired) {
        // 回复申请人提示已同意
        try {
          await sendLarkText({
            client,
            chatId,
            replyToMessageId: pendingMsg.messageId,
            markdown: "✅ 管理员已同意，正在处理你的消息",
          });
        } catch (err) {
          console.warn("[lark-access] 回复申请人通过提示失败", err);
        }

        // 重新入队重放
        if (_globalReplayHandler) {
          try {
            _globalReplayHandler(args.botId, client, pendingMsg);
            replayed = true;
          } catch (err) {
            console.error("[lark-access] 重放挂起消息失败", err);
          }
        }
      } else {
