  name: "",
  appId: "",
  appSecret: "",
  agentId: null,
  workspacePath: "",
  enabled: true,
  groupTrigger: LARK_POLICY_DEFAULTS.groupTrigger,
  triggerPrefix: "",
  sessionPolicy: LARK_POLICY_DEFAULTS.sessionPolicy,
  replyMode: LARK_POLICY_DEFAULTS.replyMode,
  ackMode: LARK_POLICY_DEFAULTS.ackMode,
};

