      body: JSON.stringify({ id: memberId }),
    });
    setMessage("已移除成员");
    await refreshMembers(selectedId);
  } catch (cause) {
    setError(cause instanceof Error ? cause.message : String(cause));
  } finally {
    setBusy(null);
  }
};

