                        onClick={() => void handleMemberDelete(m.id)}
                      >
                        移除
                      </Button>
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>
      ) : (
        <div className="text-label text-ink-faint">
          保存机器人配置后即可管理成员名单与审批请求。
        </div>
      )}
    </div>
  )}
</section>

